{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Anagliptin, with high transferability, has an oral bioavailability >73% in patients with T2DM, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Fenspiride absolute bioavailability was 90% in healthy volunteers after oral slow-release tablets versus IV, a direct human absolute measurement supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Thalidomide absolute oral bioavailability was probably high (80–100%) at low doses in fasting healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Vildagliptin absolute oral bioavailability was approximately 85% in healthy volunteers after a 50 mg oral dose versus IV infusion, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Aminoglutethimide oral bioavailability was approximately 100% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ursodeoxycholic acid, a steroid-like molecule, had 50% systemic availability in normal subjects versus IV, still above the 20% threshold and supportive.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pentazocine oral bioavailability was 18% in patients (2 x 50 mg tablets versus IV), below the 20% threshold; this is the only contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a steroidal spiro-lactone (drospirenone-like). Multiple high-transfer human absolute-bioavailability measurements (50–100%) from diverse scaffolds support high oral bioavailability, while the single low-F analogue (pentazocine, ~18%) is outweighed by this consistent high-F evidence. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; prediction relies on transferable analogues.",
    "The only low-bioavailability analogue (pentazocine) is a phenolic benzomorphan opioid with extensive first-pass metabolism; its relevance to the steroidal spiro-lactone query is uncertain despite a high transfer score."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

